from datetime import datetime
import re


_SHA256 = re.compile(r"[a-fA-F0-9]{64}\Z")


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def certificate_readiness_violations(certificate: dict[str, object], *, required_hosts: tuple[str, ...], now: datetime, minimum_validity_days: int = 30) -> tuple[str, ...]:
    if not isinstance(minimum_validity_days, int) or isinstance(minimum_validity_days, bool) or minimum_validity_days < 0:
        raise ValueError("minimum validity days must be a non-negative integer")
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    violations: list[str] = []
    if not str(certificate.get("certificate_id", "")).strip():
        violations.append("certificate_id_is_required")
    fingerprint = certificate.get("sha256_fingerprint")
    if not isinstance(fingerprint, str) or not _SHA256.fullmatch(fingerprint.replace(":", "")):
        violations.append("sha256_fingerprint_is_invalid")
    expires_at = _timestamp(certificate.get("expires_at"))
    if expires_at is None:
        violations.append("expires_at_must_be_timezone_aware")
    elif (expires_at - now).total_seconds() < minimum_validity_days * 86400:
        violations.append("certificate_validity_margin_is_insufficient")
    normalized_required = {str(host).strip().lower() for host in required_hosts if str(host).strip()}
    if len(normalized_required) != len(required_hosts) or not normalized_required:
        violations.append("required_hosts_are_invalid")
    sans = certificate.get("dns_names")
    if not isinstance(sans, (list, tuple)):
        violations.append("certificate_dns_names_are_required")
    else:
        covered = {str(host).strip().lower() for host in sans if str(host).strip()}
        for host in sorted(normalized_required - covered):
            violations.append(f"hostname_not_covered:{host}")
    return tuple(violations)


def certificate_is_ready_for_promotion(certificate: dict[str, object], **policy: object) -> bool:
    return not certificate_readiness_violations(certificate, **policy)

import unittest
from datetime import datetime, timezone

from kong_deck_gateway.certificate_readiness import certificate_is_ready_for_promotion, certificate_readiness_violations


NOW = datetime(2026, 7, 30, tzinfo=timezone.utc)


class GatewayCertificateReadinessGateTests(unittest.TestCase):
    def test_identified_certificate_with_margin_and_host_coverage_passes(self):
        certificate = {"certificate_id": "edge-2026-01", "sha256_fingerprint": "ab:" * 31 + "ab", "expires_at": "2026-12-01T00:00:00Z", "dns_names": ["api.example.com", "admin.example.com"]}
        self.assertTrue(certificate_is_ready_for_promotion(certificate, required_hosts=("api.example.com", "admin.example.com"), now=NOW))

    def test_expiry_fingerprint_and_host_failures_are_reported_together(self):
        certificate = {"certificate_id": "edge", "sha256_fingerprint": "short", "expires_at": "2026-08-01T00:00:00Z", "dns_names": ["api.example.com"]}
        violations = certificate_readiness_violations(certificate, required_hosts=("api.example.com", "admin.example.com"), now=NOW, minimum_validity_days=30)
        self.assertIn("sha256_fingerprint_is_invalid", violations)
        self.assertIn("certificate_validity_margin_is_insufficient", violations)
        self.assertIn("hostname_not_covered:admin.example.com", violations)

    def test_missing_metadata_and_invalid_policy_fail(self):
        violations = certificate_readiness_violations({}, required_hosts=("api.example.com",), now=NOW)
        self.assertIn("certificate_id_is_required", violations)
        self.assertIn("expires_at_must_be_timezone_aware", violations)
        self.assertIn("certificate_dns_names_are_required", violations)
        with self.assertRaises(ValueError):
            certificate_readiness_violations({}, required_hosts=("api.example.com",), now=NOW, minimum_validity_days=-1)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations


_ACTIONS = {"create", "update", "delete"}
_ENTITY_TYPES = {"service", "route", "consumer", "upstream", "plugin"}


def destructive_change_violations(changes: list[dict[str, object]], *, approved_by: str | None = None, change_ticket: str | None = None, backup_reference: str | None = None) -> tuple[str, ...]:
    if not changes:
        return ("at_least_one_deck_change_is_required",)
    violations: list[str] = []
    seen: set[tuple[str, str]] = set()
    has_deletion = False
    for index, change in enumerate(changes):
        entity_type = str(change.get("entity_type", "")).strip().lower()
        entity_name = str(change.get("entity_name", "")).strip()
        action = str(change.get("action", "")).strip().lower()
        if entity_type not in _ENTITY_TYPES:
            violations.append(f"change_{index}:entity_type_is_invalid")
        if not entity_name:
            violations.append(f"change_{index}:entity_name_is_required")
        if action not in _ACTIONS:
            violations.append(f"change_{index}:action_is_invalid")
        key = (entity_type, entity_name)
        if entity_name and key in seen:
            violations.append(f"change_{index}:duplicate_entity_change")
        seen.add(key)
        has_deletion = has_deletion or action == "delete"
    if has_deletion and not str(approved_by or "").strip():
        violations.append("destructive_change_requires_reviewer")
    if has_deletion and not str(change_ticket or "").strip():
        violations.append("destructive_change_requires_ticket")
    if has_deletion and not str(backup_reference or "").strip():
        violations.append("destructive_change_requires_backup_reference")
    return tuple(violations)


def deck_change_plan_is_safe(changes: list[dict[str, object]], **evidence: object) -> bool:
    return not destructive_change_violations(changes, **evidence)

from __future__ import annotations


def upstream_capacity_violations(targets: list[dict[str, object]], *, minimum_healthy_targets: int = 2, minimum_healthy_weight: int = 200, minimum_healthy_zones: int = 2) -> tuple[str, ...]:
    for name, value in (("minimum healthy targets", minimum_healthy_targets), ("minimum healthy weight", minimum_healthy_weight), ("minimum healthy zones", minimum_healthy_zones)):
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise ValueError(f"{name} must be a positive integer")
    if not targets:
        return ("at_least_one_upstream_target_is_required",)
    violations: list[str] = []
    seen_names: set[str] = set()
    healthy_targets = 0
    healthy_weight = 0
    healthy_zones: set[str] = set()
    for index, target in enumerate(targets):
        name = str(target.get("name", "")).strip()
        zone = str(target.get("zone", "")).strip()
        healthy = target.get("healthy")
        weight = target.get("weight")
        if not name:
            violations.append(f"target_{index}:name_is_required")
        elif name in seen_names:
            violations.append(f"target_{index}:name_must_be_unique")
        seen_names.add(name)
        if not zone:
            violations.append(f"target_{index}:zone_is_required")
        if not isinstance(healthy, bool):
            violations.append(f"target_{index}:healthy_must_be_boolean")
        if not isinstance(weight, int) or isinstance(weight, bool) or weight < 0:
            violations.append(f"target_{index}:weight_must_be_a_non_negative_integer")
        if healthy is True and isinstance(weight, int) and not isinstance(weight, bool) and weight >= 0:
            healthy_targets += 1
            healthy_weight += weight
            if zone:
                healthy_zones.add(zone)
    if healthy_targets < minimum_healthy_targets:
        violations.append("healthy_target_count_below_minimum")
    if healthy_weight < minimum_healthy_weight:
        violations.append("healthy_target_weight_below_minimum")
    if len(healthy_zones) < minimum_healthy_zones:
        violations.append("healthy_target_zone_diversity_below_minimum")
    return tuple(violations)


def upstream_has_failover_capacity(targets: list[dict[str, object]], **policy: object) -> bool:
    return not upstream_capacity_violations(targets, **policy)
